// Pure helpers shared by the globe UI and renderer. Only source records are processed.
export function sampleExtremes(records){const rows=records.filter(r=>r.category==='weather'&&Number.isFinite(r.current?.temperature_2m));if(!rows.length)return null;return {hot:rows.reduce((a,b)=>a.current.temperature_2m>b.current.temperature_2m?a:b),cold:rows.reduce((a,b)=>a.current.temperature_2m<b.current.temperature_2m?a:b),count:rows.length}}
export function interestingPoint(records,now=Date.now()){
 const events=records.filter(r=>r.category==='event'&&!r.stale&&r.at<=now&&now-r.at<7*86400000).sort((a,b)=>b.at-a.at||a.id.localeCompare(b.id));if(events.length)return events[0];
 return records.filter(r=>r.category==='weather'&&!r.stale&&now-r.at<3600000&&(r.current?.precipitation>0||r.current?.snowfall>0)).sort((a,b)=>(b.current.precipitation||0)-(a.current.precipitation||0)||b.at-a.at)[0]||null;
}
export function precipitationSamples(records){return records.filter(r=>r.category==='weather'&&Number.isFinite(r.latitude)&&Number.isFinite(r.longitude)).flatMap(r=>{const w=r.current||{},snow=Number.isFinite(w.snowfall)&&w.snowfall>0,rain=Number.isFinite(w.precipitation)&&w.precipitation>0;return snow||rain?[{...r,snow}]:[]})}
export function precipitationTexture(canvas,records){const x=canvas.getContext('2d'),w=canvas.width,h=canvas.height;x.clearRect(0,0,w,h);for(const r of precipitationSamples(records)){const px=(r.longitude+180)/360*w,py=(90-r.latitude)/180*h,ry=3/180*h,rx=ry/Math.max(.25,Math.cos(r.latitude*Math.PI/180));for(const offset of [-w,0,w]){x.save();x.translate(px+offset,py);x.scale(rx,ry);const g=x.createRadialGradient(0,0,0,0,0,1);g.addColorStop(0,r.snow?'rgba(255,255,255,.7)':'rgba(79,182,245,.65)');g.addColorStop(1,'rgba(79,182,245,0)');x.fillStyle=g;x.beginPath();x.arc(0,0,1,0,Math.PI*2);x.fill();x.restore()}}}
// Cache only public world snapshots. Never community, identity or private notices.
function openWorldCache(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('No storage'));const req=indexedDB.open('meteosocial-world',1);req.onupgradeneeded=()=>req.result.createObjectStore('snapshots');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
export async function worldCacheRead(kind){try{const db=await openWorldCache();return await new Promise(resolve=>{const tx=db.transaction('snapshots'),req=tx.objectStore('snapshots').get(kind);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>resolve(null);tx.oncomplete=()=>db.close();tx.onabort=()=>{db.close();resolve(null)}})}catch{return null}}
export async function worldCacheWrite(kind,value){try{const db=await openWorldCache();await new Promise(resolve=>{const tx=db.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(value,kind);tx.oncomplete=()=>{db.close();resolve()};tx.onabort=()=>{db.close();resolve()}})}catch{}}
